#include <stdio.h>

struct Cat {
    char name[20];
    int fish;
};

int main(void) {
    struct Cat cats[3] = {
        {"小橘", 0},
        {"狸花", 0},
        {"大肥鱼", 0}
    };

    for (int i = 0; i < 3; i++) {
        if (scanf("%d", &cats[i].fish) != 1) {
            return 1;
        }
    }

    int total = 0;
    for (int i = 0; i < 3; i++) {
        printf("%s 吃了 %d 条{unit}\n", cats[i].name, cats[i].fish);
        total = total + cats[i].fish;
    }
    printf("一共 %d 条{unit}\n", total);
    return 0;
}

explanationTemplate:
这道题练的是**一排猫**，跟「一排碗」是同一套本事，只是每一只身上多带了几个格子喵。

**① 一排猫怎么摆？** 名字交出来的时候，正好可以**一次填好一排**（下面按排版换行写，真写的时候花括号位置不影响意思）：

```c
struct Cat cats[3] =
{
    {
        "小橘", 0
    },
    {
        "狸花", 0
    },
    {
        "大肥鱼", 0
    }
};
```

外面那层花括号是「这一排」，里面每一小对是「一只猫身上的格子」。这是 C 给图纸留的甜头：**摆一排的时候可以一次填完，不用一格一格赋值。** 食量先填 0 占个位 —— 反正下一步就读进来盖掉它。

**② 读进来的时候要问门牌号。** `scanf("%d", &cats[i].fish)`：先挑出第 i 只猫，再进它的 `fish` 格 —— 那是一只碗，所以前面得写 `&`。（对照着记：`cats[i].name` 是一排碗的名字，读它的时候**不用**写 `&`。）

**③ 跑圈一只只报、顺路算总账。** 走一圈同时干两件事：印这一只，再把它的食量加进 `total`。这里最容易写歪的就是那句累加 —— 一定要写成 `total = total + cats[i].fish;`，写成 `total = cats[i].fish;` 的话，前面几只的账会被一只只盖掉，最后只剩最后一只的数。

**④ 点号的顺序别弄反。** `cats[i].name` 读作「先挑出第 i 只猫，再进它的名字格」。写成 `cats.name[i]` 翻译官喵会拦你 —— 因为 `cats` 是**一排猫**，不是一只猫，它身上没有 `name` 这格喵。
